import json, subprocess, sys

def q(query):
    r = subprocess.run(['curl','-s','-X','POST','https://api.linear.app/graphql',
        '-H','Content-Type: application/json','-H','Authorization: Bearer <TOKEN>',
        '-d',json.dumps({'query':query})], capture_output=True, text=True)
    d = json.loads(r.stdout)
    if d.get('errors'):
        print('ERR:', d['errors'][0]['message']); return None
    return d['data']

if __name__ == '__main__':
    mode = sys.argv[1] if len(sys.argv)>1 else 'q'
    if mode == 'query':
        print(json.dumps(q(sys.argv[2]), indent=1))
    elif mode == 'types':
        d = q('{ __schema { queryType { fields { name } } mutationType { fields { name } } } }')
        if d:
            print('QUERIES:', [f['name'] for f in d['__schema']['queryType']['fields']])
            m = d['__schema'].get('mutationType')
            if m: print('MUTATIONS:', [f['name'] for f in m['fields']])
    elif mode == 'fields':
        d = q('{ __type(name: "%s") { fields { name args { name } } } }' % sys.argv[2])
        if d and d['__type']:
            for f in d['__type']['fields']:
                args = ', '.join(f['args'][a]['name'] for a in f['args'])
                print(f['name'], '('+args+')')
EOF
